`timescale 1ns / 1ps
// 1023-chip PN code sampled twice per chip. Constant rotations synthesize as
// registers plus fixed wiring instead of 128 independent dynamic selectors.
module pn_code (
    input  wire          clk,
    input  wire          rst,
    input  wire          init_i,
    input  wire          din_en_i,//bank rd_en开启则不停滑动码相位
    input  wire [7:0]    row_addr_i,
    input  wire [10:0]   code_phase_i,
    output reg           dout_en_o,
    output reg [127:0]   pn_o
);

// Direct 2046-bit representation. Each visible bit of the original literal is
// duplicated; for example suffix 01011 becomes 00_11_00_11_11.
localparam [2045:0] PN_2046 = 2046';

reg [2045:0] pn_shift;
wire unused_code_phase = ^code_phase_i;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        pn_shift  <= PN_2046;
        pn_o      <= 128'd0;
        dout_en_o <= 1'b0;
    end else if (init_i) begin
        pn_shift  <= PN_2046;
        pn_o      <= 128'd0;
        dout_en_o <= 1'b0;
    end else begin
        dout_en_o <= din_en_i;
        if (din_en_i) begin
            pn_o <= pn_shift[127:0];
            if (row_addr_i == 8'd255)
                pn_shift <= {pn_shift[94:0], pn_shift[2045:95]};//读完一次下一轮PN错开1位，第0次不挪：(255*128+x) mod 2046 = 2045 (-1),x=95。第一轮相位=0，第二轮=-1
            else
                pn_shift <= {pn_shift[127:0], pn_shift[2045:128]};
        end
    end
end

endmodule

